class Track {public Vector3[] p;public float[] s;public float length;public Track(Vector3[] source){p=source;s=new float[p.Length];for(int i=1;i<p.Length;i++)s[i]=s[i-1]+Vector3.Distance(p[i],p[i-1]);length=s.Last();}public Vector3 At(float d){d=Mathf.Clamp(d,0,length);int i=Array.BinarySearch(s,d);if(i>=0)return p[i];i=~i;return Vector3.Lerp(p[Mathf.Max(0,i-1)],p[Mathf.Min(i,p.Length-1)],Mathf.InverseLerp(s[Mathf.Max(0,i-1)],s[Mathf.Min(i,p.Length-1)],d));}public Vector3 Right(float d){Vector3 tangent=At(d+.14f)-At(d-.14f);return Vector3.Cross(Vector3.up,tangent).normalized;}public Vector3 Edge(float d,float offset,float y=0){return At(d)+Right(d)*offset+Vector3.up*y;}}
static void FitStone(SkyRuinMesh mesh,Track t,float a,float b,float left,float right,float top,float depth,float bevel=.025f){mesh.Slab(new[]{t.Edge(a,left,top),t.Edge(b,left,top),t.Edge(b,right,top),t.Edge(a,right,top)},depth,bevel);}
