Database.SaveAssets();EditorSceneManager.SaveScene(scene);Shots();RefinedShots();Audit();WideAudit();EditorSceneManager.SaveScene(scene);}
static void Refine06(){scene=SceneManager.GetSceneByPath(ScenePath);if(!scene.IsValid())throw new Exception("Open 10006a first");SceneManager.SetActiveScene(scene);root=scene.GetRootGameObjects().First(g=>g.name=="10006a_Suspended_Ruin_Causeways").transform;if(root.Find("20_Refined_Masonry_And_Architecture"))throw new Exception("Refinement already applied");EditorSceneManager.SaveScene(scene,W+"/outputs/10006aRefined/10006a_before_refinement.unity",true);rng=new System.Random(6061207);counter=2600;stone=AssetDatabase.LoadAssetAtPath<Material>(Root+"/Materials/Weathered_Limestone.mat");dark=AssetDatabase.LoadAssetAtPath<Material>(Root+"/Materials/Carved_Shadow_Stone.mat");gold=AssetDatabase.LoadAssetAtPath<Material>(Root+"/Materials/Aged_Brass_Inlay.mat");cliff=AssetDatabase.LoadAssetAtPath<Material>(Root+"/Materials/Teal_Fractured_Rock.mat");stone.SetColor("_BaseColor",new Color(.63f,.68f,.64f));dark.SetColor("_BaseColor",new Color(.37f,.43f,.40f));gold.SetColor("_BaseColor",new Color(.63f,.49f,.25f));EditorUtility.SetDirty(stone);EditorUtility.SetDirty(dark);EditorUtility.SetDirty(gold);lightStone=Mat("Refined_Edge_Limestone",new Color(.70f,.73f,.65f));slate=Mat("Refined_Alternate_Flagstone",new Color(.53f,.59f,.56f));moss=Mat("Deep_Crevice_Moss",new Color(.22f,.34f,.17f));StoneRelief();Audit();var pass=Group("20_Refined_Masonry_And_Architecture");string[] names={"07_Entry_Serpentine_Bridge","08_Ascending_Causeway","09_Great_Sanctuary_Span","10_Altar_Outer_Loop","11_Altar_Return_Loop","12_Archive_Treasure_Spur"};float[] widths={4.5f,4.8f,5.6f,3.8f,3.7f,3.9f};for(int n=0;n<names.Length;n++){var original=root.Find(names[n]);foreach(Transform child in original){if(child.GetComponent<MeshRenderer>())child.gameObject.SetActive(false);}RefinedBridge(new Track(routes[n]),widths[n],names[n]+"_R2",pass,n);}
foreach(var t in root.GetComponentsInChildren<Transform>().Where(t=>t.name.EndsWith("_Voussoir_Arch")||t.name.EndsWith("_Carved_Crown")))t.gameObject.SetActive(false);PlatformDetail(pass);EntranceDetail(pass);ScenicDetail(pass);AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(scene);Shots();RefinedShots();Audit();WideAudit();EditorSceneManager.SaveScene(scene);}
static void StoneRelief(){int size=256;var height=new Texture2D(size,size,TextureFormat.RGB24,false);for(int y=0;y<size;y++)for(int x=0;x<size;x++){float a=Mathf.PerlinNoise(x/31f+13,y/31f+9),b=Mathf.PerlinNoise(x/8f,y/8f),c=Mathf.PerlinNoise(x/2.1f,y/2.1f);float v=a*.55f+b*.3f+c*.15f;float line=Mathf.Abs(Mathf.Sin((x+Mathf.PerlinNoise(x/50f,y/50f)*45+y*.43f)*.09f));if(line<.025f)v-=.1f;height.SetPixel(x,y,new Color(v,v,v));}height.Apply();string path=Root+"/Textures/Refined_Stone_Height.png";File.WriteAllBytes(path,height.EncodeToPNG());Object.DestroyImmediate(height);AssetDatabase.ImportAsset(path);var imp=(TextureImporter)AssetImporter.GetAtPath(path);imp.textureType=TextureImporterType.NormalMap;imp.convertToNormalmap=true;imp.heightmapScale=.055f;imp.wrapMode=TextureWrapMode.Repeat;imp.SaveAndReimport();var bump=AssetDatabase.LoadAssetAtPath<Texture2D>(path);foreach(var m in new[]{stone,dark,lightStone,slate}){m.SetTexture("_BumpMap",bump);m.SetFloat("_BumpScale",.35f);m.EnableKeyword("_NORMALMAP");m.SetFloat("_Smoothness",.08f);EditorUtility.SetDirty(m);}}
static void RefinedBridge(Track t,float w,string label,Transform pass,int index){var g=Group(label,pass);var core=new SkyRuinMesh();var floor=new SkyRuinMesh();var alternate=new SkyRuinMesh();var borders=new SkyRuinMesh();var rails=new SkyRuinMesh();var relief=new SkyRuinMesh();var trims=new SkyRuinMesh();
// Continuous swept geometry with shared edge positions closes seams at bends, including outer parapet corners.
for(float d=0;d<t.length;d+=.42f){float e=Mathf.Min(d+.42f,t.length);FitStone(core,t,d,e,-w/2-.02f,w/2+.02f,-.065f,.91f,.005f);foreach(int sign in new[]{-1,1}){float l=sign*(w/2+.05f)-.24f,r=l+.48f;FitStone(borders,t,d,e,l,r,-.12f,1.12f,.015f);FitStone(trims,t,d,e,l-.07f,r+.07f,-.44f,.17f,.015f);}}
// Rows use true arc length and curve-following corners, rather than straight boxes placed by point index.
int row=0;for(float a=0;a<t.length;a+=1.04f){float b=Mathf.Min(a+1.04f,t.length);for(int j=0;j<4;j++){float l=-w/2+j*w/4+.012f,r=-w/2+(j+1)*w/4-.012f;FitStone((row+j)%5==0?alternate:floor,t,a+.007f,Mathf.Max(a+.008f,b-.007f),l,r,.018f+R(0,.008f),.14f,.018f);}row++;}
for(float a=.25f;a<t.length-.2f;a+=.92f){float b=Mathf.Min(a+.92f,t.length-.15f);foreach(int sign in new[]{-1,1}){float center=sign*(w/2+.12f);FitStone(rails,t,a,b,center-.22f,center+.22f,.94f,.91f,.018f);FitStone(trims,t,a,b,center-.31f,center+.31f,1.1f,.18f,.025f);float mid=(a+b)*.5f;Vector3 side=t.Right(mid)*sign;Vector3 dir=(t.At(mid+.1f)-t.At(mid-.1f)).normalized;Vector3 c=t.Edge(mid,center+sign*.231f,.48f);float yaw=Mathf.Atan2(dir.x,dir.z)*Mathf.Rad2Deg;
// Raised square-spiral stone plaques create readable relief in the rail faces.
relief.Block(c+Vector3.up*.2f,.06f,.55f,.06f,yaw,.01f);relief.Block(c-Vector3.up*.2f,.06f,.55f,.06f,yaw,.01f);foreach(float z in new[]{-.24f,.24f})relief.Block(c+dir*z,.065f,.07f,.40f,yaw,.01f);relief.Block(c+dir*.05f,.075f,.27f,.075f,yaw,.01f);
} }
for(float d=.7f;d<t.length-.4f;d+=4.4f){foreach(int sign in new[]{-1,1}){float x=sign*(w/2+.12f);float yaw=Mathf.Atan2(t.Right(d).z,-t.Right(d).x)*Mathf.Rad2Deg;Vector3 p=t.Edge(d,x);rails.Block(p+Vector3.up*.2f,.85f,.85f,.24f,yaw,.06f);rails.Block(p+Vector3.up*1.43f,.59f,.64f,1.25f,yaw,.07f);trims.Block(p+Vector3.up*1.58f,.86f,.88f,.19f,yaw,.065f);trims.Wedge(p+Vector3.up*1.73f,.01f,.33f,0,Mathf.PI*2,.15f,8);}}
Mesh(core,label+"_Mortared_Seamless_Bridge_Core",dark,g,true);Mesh(floor,label+"_Fitted_Curving_Flagstones",stone,g,true);Mesh(alternate,label+"_Subtle_Slate_Inserts",slate,g,true);Mesh(borders,label+"_Dressed_Stone_Fascia",stone,g);Mesh(rails,label+"_Closed_Masonry_Parapets",stone,g,true);Mesh(trims,label+"_Sculpted_Coping_And_Cornices",lightStone,g);Mesh(relief,label+"_Raised_Spiral_Frieze",lightStone,g);ArchedSupports(t,w,g,label);}
static void ArchedSupports(Track t,float w,Transform g,string label){var arch=new SkyRuinMesh();var seams=new SkyRuinMesh();int spans=Mathf.Max(1,Mathf.RoundToInt(t.length/9f));for(int n=0;n<spans;n++){float a=n*t.length/spans,b=(n+1)*t.length/spans;foreach(int sign in new[]{-1,1})for(int j=0;j<16;j++){float u=j/16f,v=(j+1)/16f;float d=Mathf.Lerp(a,b,u),e=Mathf.Lerp(a,b,v);Vector3 p=t.Edge(d,sign*(w/2-.08f),-1.02f-3.3f*(1-Mathf.Sin(u*Mathf.PI))),q=t.Edge(e,sign*(w/2-.08f),-1.02f-3.3f*(1-Mathf.Sin(v*Mathf.PI)));Vector3 r=t.Right(d)*.30f,s=t.Right(e)*.30f;Vector3 low=Vector3.up*.74f;arch.Face(p-r,q-s,q-s-low,p-r-low);arch.Face(p+r,p+r-low,q+s-low,q+s);arch.Face(p-r,p+r,q+s,q-s);arch.Face(p-r-low,q-s-low,q+s-low,p+r-low);Vector3 c=(p+q)*.5f;float yaw=Mathf.Atan2((q-p).x,(q-p).z)*Mathf.Rad2Deg;seams.Block(c,.7f,.07f,.8f,yaw,.02f);}Vector3 pier=t.At(a)-Vector3.up*4;float yaw2=Mathf.Atan2(t.Right(a).z,-t.Right(a).x)*Mathf.Rad2Deg;arch.Block(pier,w+.5f,1.05f,.32f,yaw2,.08f);arch.Block(pier-Vector3.up*.45f,1.45f,1.35f,1.7f,yaw2,.12f);seams.Block(pier-Vector3.up*2.1f,1.9f,1.75f,.26f,yaw2,.08f);arch.Rock(pier-Vector3.up*2.5f,1.1f,2.8f,8,900+n);}Mesh(arch,label+"_Curved_Vaulted_Arch_Ribs",stone,g);Mesh(seams,label+"_Arch_Keystones_And_Joints",lightStone,g);}
static bool NearRoute(Vector3 p,float distance){return routes.Any(r=>r.Any(q=>Vector2.Distance(new Vector2(p.x,p.z),new Vector2(q.x,q.z))<distance));}
static void PlatformDetail(Transform pass){var g=Group("Carved_Plaza_Architecture",pass);foreach(var tuple in new[]{Tuple.Create(court,9.2f,"Court"),Tuple.Create(hub,7.2f,"Junction"),Tuple.Create(boss,12f,"Sanctuary"),Tuple.Create(shrine,5f,"Altar"),Tuple.Create(treasure,4.2f,"Balcony")}){Vector3 c=tuple.Item1;float radius=tuple.Item2;var edge=new SkyRuinMesh();var medallion=new SkyRuinMesh();for(int i=0;i<64;i++){float a=i*Mathf.PI*2/64,b=(i+1)*Mathf.PI*2/64;edge.Wedge(c-Vector3.up*.16f,radius-.24f,radius+.23f,a,b,.38f,2);edge.Wedge(c-Vector3.up*.65f,radius-.12f,radius+.12f,a,b,.22f,2);}medallion.Ring(c+Vector3.up*.075f,2.5f,.13f,.04f);medallion.Ring(c+Vector3.up*.075f,2.85f,.08f,.04f);for(int i=0;i<12;i++){float a=i*Mathf.PI/6;Vector3 p=c+P(Mathf.Cos(a)*2.65f,.08f,Mathf.Sin(a)*2.65f);medallion.Block(p,.11f,.36f,.05f,90-a*Mathf.Rad2Deg,.02f);}Mesh(edge,tuple.Item3+"_Restored_Segmented_Rim",lightStone,g);Mesh(medallion,tuple.Item3+"_Carved_Compass_Rosette",gold,g);
// Back arcades and buttressed fragments avoid blocking entrances and combat floors.
for(int i=0;i<9;i++){float a=i*6.28318f/9;var p=c+P(Mathf.Cos(a)*(radius-.9f),0,Mathf.Sin(a)*(radius-.9f));if(NearRoute(p,3.3f))continue;if(tuple.Item3=="Junction"&&p.z<c.z)continue;if(tuple.Item3=="Sanctuary"&&p.z>c.z+5)continue;if(i%3==0)Prop("P_FW01_Ruins_Decor_Column_3m_01",g,p,1.0f,R(0,360),true);else if(i%3==1)Prop("P_FW01_Ruins_Wall_Half_Low_Broken_01",g,p,2.5f,90-a*Mathf.Rad2Deg,true);else Prop("P_FW01_Debris_Rubble_Small_01",g,p,1.6f,R(0,360));}
for(int i=0;i<12;i++){float a=R(0,6.28318f);var p=c+P(Mathf.Cos(a)*(radius-.6f),.035f,Mathf.Sin(a)*(radius-.6f));if(!NearRoute(p,2.8f))Prop("P_fwOF_Fern_02",g,p,R(.7f,1.1f),R(0,360));}}
var hero=Group("Sanctuary_Colonnade_And_Guardians",pass);foreach(float x in new[]{-9f,-6f,6f,9f})Prop("P_FW01_Ruins_Decor_Column_4m_01",hero,boss+P(x,0,6.2f),1.1f);foreach(float sign in new[]{-1f,1f}){Vector3 p=boss+P(sign*5.0f,0,3.7f);var baseM=new SkyRuinMesh();baseM.Wedge(p+Vector3.up*.28f,.01f,1.25f,0,Mathf.PI*2,.28f,8);baseM.Wedge(p+Vector3.up*.52f,.01f,1.0f,0,Mathf.PI*2,.27f,8);Mesh(baseM,"Guardian_Octagonal_Plinth_"+(sign<0?"West":"East"),stone,hero,true);Prop("P_fwOF_Statue_01",hero,p+Vector3.up*.52f,2.2f,180,true);}
// Decorative bridge portals frame long spans without placing columns on the walkable strip.
foreach(var item in new[]{Tuple.Create(2,.46f),Tuple.Create(3,.5f)}){var t=new Track(routes[item.Item1]);float d=t.length*item.Item2;Vector3 p=t.At(d);Vector3 tangent=t.At(d+.2f)-t.At(d-.2f);float yaw=Mathf.Atan2(tangent.x,tangent.z)*Mathf.Rad2Deg;Prop("P_FW01_Ruins_Decor_Arch_03",hero,p, item.Item1==2?7.2f:5.4f,yaw,true);}}
