static void WideAudit(){Physics.SyncTransforms();int samples=0,gaps=0;var lines=new List<string>();foreach(var p in routes){var t=new Track(p);for(float d=.2f;d<t.length;d+=.4f)foreach(float frac in new[]{-.4f,-.2f,0,.2f,.4f}){int n=routes.IndexOf(p);float[] widths={4.5f,4.8f,5.6f,3.8f,3.7f,3.9f};var q=t.Edge(d,frac*widths[n]);var hits=Physics.RaycastAll(q+Vector3.up*.7f,Vector3.down,1.6f);samples++;if(!hits.Any(h=>h.collider.gameObject.scene==scene)){gaps++;lines.Add("GAP "+q);}}}lines.Insert(0,"Full-width bridge samples="+samples+"; gaps="+gaps);File.WriteAllLines(W+"/outputs/10006aRefined/FullWidthValidation.txt",lines);}
